create table xxcus.xxcmp_alerts (
    alert_id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    alert_rule_id         number not null enable,
    alert_key             varchar2(200 byte) not null enable,
    party_id              number,
    case_id               number,
    alert_message         varchar2(1000 byte) not null enable,
    due_date              date,
    alert_status          varchar2(30 byte) default 'OPEN' not null enable,
    acknowledged_by       varchar2(255 byte),
    acknowledged_date     timestamp(6),
    review_request_id     number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_alerts
    add constraint xxcmp_alerts_ck1
        check ( alert_status in ( 'OPEN', 'ACKNOWLEDGED', 'CLOSED' ) ) enable;

alter table xxcus.xxcmp_alerts
    add constraint xxcmp_alerts_pk primary key ( alert_id )
        using index enable;

alter table xxcus.xxcmp_alerts
    add constraint xxcmp_alerts_uk1 unique ( alert_rule_id,
                                             alert_key )
        using index enable;


